import { OSHCUT_DISPATCH_ENVELOPE } from "./oshcutDispatchAuthorization.js";
import {
  classifyProviderPortalSnapshot,
  isAllowedProviderUrl,
  type ProviderPortalDefinition,
} from "./providerPortalKernel.js";

/**
 * Generated by `npm run fixture:onboard -- oshcut --stage=live` (OVD-687).
 *
 * Default-off production portal stub for OSH Cut. It runs on the shared
 * provider portal kernel (and `PortalQuoteWorkflowAdapter` once registered),
 * but is deliberately inert:
 *
 * - it is not registered in `worker/src/adapters/index.ts`;
 * - its envelope is not reviewed, so no permit can authorize it;
 * - `assessEligibility` returns `unavailable` before any session read or
 *   browser launch, and `extractOffers` returns nothing.
 *
 * Routes, selectors, and locators below are placeholders, not observations of
 * the live portal. Replacing them requires an authorized live DOM review
 * (a protected action under AGENTS.md).
 */
export const OSHCUT_PRODUCTION_ADAPTER_REVISION = "oshcut-production-adapter.v0-unreviewed";
export const OSHCUT_ALLOWED_HOSTS = ["oshcut.com", "www.oshcut.com"] as const;

/** Placeholder offer locator table; pinned by the generated browser fixture once reviewed. */
export const OSHCUT_PRODUCTION_LOCATORS = {
  revision: "oshcut-production-locators.v0-unreviewed",
  card: "[data-ovd-unreviewed-oshcut-option]",
  optionIdAttribute: "data-option-id",
  fields: {
    label: "[data-label]",
    quantity: "[data-quantity]",
    unitPrice: "[data-unit-price]",
    totalPrice: "[data-total-price]",
    currency: "[data-currency]",
    leadBusinessDays: "[data-lead-business-days]",
  },
} as const;

const OSHCUT_TERMINAL_SIGNALS: ProviderPortalDefinition["terminalSignals"] = {
  login: [/\b(?:log ?in|sign[ -]?in|session expired)\b/i],
  captcha: [/captcha|verify you are human|security check/i],
  manualReview: [/manual review|engineering review|requires review/i],
  configurationRequired: [/select material|configure (?:your )?part/i],
  unavailable: [/service unavailable|maintenance/i],
};

export function buildOshcutProductionPortalDefinition(): ProviderPortalDefinition {
  return {
    provider: "oshcut",
    displayName: "OSH Cut",
    manifestRevision: "provider-manifest.v1",
    envelopeRevision: "oshcut-quote-envelope.v1",
    adapterRevision: OSHCUT_PRODUCTION_ADAPTER_REVISION,
    accountMode: "existing_authenticated_account",
    routes: {
      publicUrl: "https://www.oshcut.com/online-metal-fabrication/",
      loginUrl: "https://www.oshcut.com/online-metal-fabrication/",
      uploadUrl: "https://www.oshcut.com/online-metal-fabrication/",
    },
    allowedHosts: OSHCUT_ALLOWED_HOSTS,
    selectors: { cadUpload: "input[data-ovd-unreviewed-oshcut-upload]" },
    supportedFileExtensions: ["3dm", "ai", "catpart", "dxf", "iges", "igs", "ipt", "jt", "par", "sab", "sat", "sldprt", "step", "svg", "x_t"],
    terminalSignals: OSHCUT_TERMINAL_SIGNALS,
    requirements: { quoteOnly: true, orderProhibited: true, isolatedSession: true },
    productionDispatch: { envelope: { ...OSHCUT_DISPATCH_ENVELOPE } },
    hooks: {
      // Default-off: no reviewed portal evidence exists, so even a fully
      // authorized dispatch stops here before any session read or launch.
      assessEligibility: () => ({ state: "unavailable", reason: "oshcut_reviewed_portal_evidence_missing" }),
      configure: () => undefined,
      classifyPortalState: (snapshot) => {
        if (!isAllowedProviderUrl(snapshot.url, OSHCUT_ALLOWED_HOSTS)) return "unexpected_origin";
        const state = classifyProviderPortalSnapshot(snapshot, OSHCUT_TERMINAL_SIGNALS);
        return state === "ready" ? "selector_drift" : state;
      },
      extractOffers: () => [],
    },
  };
}
